    argsman.add_arg("-llmq-qvvec-sync=<quorum_name>:<mode>", "Defines from which LLMQ type the masternode should sync quorum verification vectors. Can be used multiple times with different LLMQ types. <mode>: 0 (sync always from all quorums of the type defined by <quorum_name>), 1 (sync from all quorums of the type defined by <quorum_name> if a member of any of the quorums)", ALLOW_ANY, Masternode);
    argsman.add_arg("-masternodeblsprivkey=<hex>", "Set the masternode BLS private key and enable the client to act as a masternode", ALLOW_ANY | SENSITIVE, Masternode);
